using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
using Elevator.Core.Application;
using Elevator.Core.Project;using Elevator.Core.Calculations;using Elevator.Solution.Desktop;using Elevator.Solution.Bridge;
using Elevator.Reporting.Sheet;
using Elevator.Reporting.DesignNotes;
using Elevator.Reporting.Docx;
using Elevator.Reporting.Figures;
public static class SafetyPitUiTests
{
 static MainWindow w;static string output;static int checks;static List<string> names=new List<string>();
 static object Get(string n){return typeof(MainWindow).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);}static void Set(string n,object v){typeof(MainWindow).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(w,v);}static object Call(string n,params object[] a){return typeof(MainWindow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,a);}
 static IEnumerable<DependencyObject> Tree(DependencyObject n){yield return n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var c in Tree(VisualTreeHelper.GetChild(n,i)))yield return c;}
 static Dictionary<string,TextBox> Editors(){return (Dictionary<string,TextBox>)Get("editors");}static Dictionary<string,ComboBox> Choices(){return (Dictionary<string,ComboBox>)Get("safetyPitChoices");}static ProjectSession Session(){return (ProjectSession)Get("session");}static CalculationWorkspace Space(){return (CalculationWorkspace)Get("calculations");}static SafetyPitCalculationResult Result(){return (SafetyPitCalculationResult)Get("safetyPitResult");}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;names.Add(name);}static void Click(string name){w.UpdateLayout();if(name.StartsWith("Calculate ")){/* Calculate buttons were replaced by live calculation: run the debounced calculation now. */Call("RunLiveCalculation");return;}Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==name).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}static string Text(){return String.Join("\n",Tree((DependencyObject)Get("safetyPitResults")).OfType<TextBlock>().Select(t=>t.Text));}
 static async Task Ready(){w.UpdateLayout();await Task.Delay(150);w.UpdateLayout();}
 static async Task Pit(){await Ready();var section=Tree(w).OfType<Expander>().First(x=>Convert.ToString(x.Header)=="Safety gear & pit loads");section.IsExpanded=true;section.BringIntoView();await Ready();}
 static async Task Choose(string field,string id){await Pit();var box=Choices()[field];int index=0;foreach(var item in box.Items){if(Convert.ToString(item.GetType().GetProperty("Id").GetValue(item,null))==id)break;index++;}Check(index<box.Items.Count,"Choice available: "+field+" = "+id);box.SelectedIndex=index;await Ready();}
 static async Task Shot(string name){await Ready();Call("Screenshot",Path.Combine(output,name+".png"));}
 [STAThread]public static int Main(string[] args)
 {
  output=args[0];Directory.CreateDirectory(output);var app=new Application();w=new MainWindow(new string[0]);Set("smoke",true);int exit=1;
  w.Loaded+=async(sender,eventArgs)=>{try{
   Call("ShowPage","CALCULATIONS");await Pit();Check(Session().Project.Calculations.Mode=="Basic"&&Choices().Values.Count(box=>box.IsVisible)==5&&new[]{"CarMassKg","CounterweightMassKg","MachineMassKg","CarSideAdditionalSuspendedMassKg","CounterweightSideAdditionalSuspendedMassKg"}.All(f=>Editors().ContainsKey("Calculations."+f))&&!Editors().ContainsKey("Calculations.MachineCgOffsetXMm"),"New Basic page has compact pit choices (gear, guides, buffer type, buffer counts) and the shared mass editors");
   // DESIGN-FLOW stage 2: a new project's event inputs follow the presets (v = 1.0 m/s: progressive gear, energy-accumulation buffers, 2 guides, 1 / 1 buffers).
   var sp=Session().Project.Calculations.SafetyPit;Check(sp.SafetyGearType=="Progressive"&&sp.CarGuideCount==2&&sp.CarBufferCount==1&&sp.CounterweightBufferCount==1&&sp.BufferType=="EnergyAccumulation"&&Convert.ToString(Choices()["SafetyGearType"].SelectedValue)=="Progressive"&&Convert.ToString(Choices()["BufferType"].SelectedValue)=="EnergyAccumulation","New project event inputs follow the presets and are shown selected");Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN.HasValue&&Result().P6.PerComponentLoadN.HasValue&&Result().P7.PerComponentLoadN.HasValue,"New project P5–P7 available with no input");
   var bin=AppDomain.CurrentDomain.BaseDirectory;var p=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(bin,"reviewed-example.elevator.json")));p.Info.Name="SYNTHETIC NOTE UI VERIFICATION — NOT PROJECT DEFAULTS";Set("session",new ProjectSession(p));Call("ResetCalculations");Call("ShowPage","GENERAL");Editors()["Elevator.CapacityKg"].Text="480";Call("Commit");Call("ShowPage","CALCULATIONS");Editors()["Calculations.CarMassKg"].Text="500";Editors()["Calculations.CounterweightMassKg"].Text="740";Editors()["Calculations.MachineMassKg"].Text="300";Editors()["Calculations.CarSideAdditionalSuspendedMassKg"].Text="600";await Pit();Check(Choices()["CarAdditionalMassAllocation"].IsVisible,"Positive additional mass immediately reveals allocation without navigation");Click("Calculate load distribution");Check(Space().Result.Reactions!=null,"Basic P1–P4 works while all P5–P7 choices are missing");
   await Choose("SafetyGearType","Progressive");await Choose("CarGuideCount","2");await Choose("CarBufferCount","1");await Choose("CounterweightBufferCount","1");await Choose("CarAdditionalMassAllocation","AllParticipates");Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN==15800&&Result().P5.GroupLoadN==31600&&Result().P6.GroupLoadN==63200&&Result().P7.GroupLoadN==29600,"Actual UI reproduces all three independent note fixtures without guide division");Check(Text().Contains("per car guide rail")&&Text().Contains("per buffer pit support")&&Text().Contains("total group"),"Physical locations, N units and per-component/group meanings rendered");
   var section=Tree(w).OfType<Expander>().First(x=>Convert.ToString(x.Header)=="Safety gear & pit loads");section.BringIntoView();await Shot("01-compact-safety-pit-form");((DependencyObject)Get("safetyPitResults")).AsFramework().BringIntoView();await Shot("02-p5-p6-p7-note-results");
   var detail=Tree(w).OfType<Expander>().First(x=>Convert.ToString(x.Header)=="Equations & event masses");detail.IsExpanded=true;detail.BringIntoView();await Shot("03-equations-mass-rule-basis");Check(Text().Contains("10 N/kg")&&Text().Contains("4 × 9.81")&&Text().Contains("Rule version")&&!Text().Contains("Source SHA-256"),"Expanded substitutions retain rounded coefficient versus g and the rule version (no rule-basis remark)");detail.IsExpanded=false;
   Editors()["Calculations.CarMassKg"].Text="550";Check(Result()==null&&!Text().Contains("15800"),"Mass edit immediately hides old event numbers");Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN==16300&&Result().P6.GroupLoadN==65200&&Result().P7.GroupLoadN==29600,"Recalculation changes participating assembly only");
   Click("Calculate load distribution");var prior=Space().Result;await Choose("CarBufferCount","2");Check(Object.ReferenceEquals(prior,Space().Result)&&Space().IsCurrent(Session().Project,(DesignContext)Get("context")),"Pit-only edit preserves current Basic chassis result");Click("Calculate P5–P7");Check(Result().P6.PerComponentLoadN==null&&Result().P5.PerComponentLoadN.HasValue&&Text().Contains("explicit sharing"),"Multiple buffers not silently divided; independent other results available");await Choose("CarBufferSharing","EqualSharing");Click("Calculate P5–P7");Check(Result().P6.GroupLoadN==65200&&Result().P6.PerComponentLoadN==32600,"Explicit equal sharing preserves group and yields per-buffer value");((DependencyObject)Get("safetyPitResults")).AsFramework().BringIntoView();await Shot("04-two-buffers-explicit-sharing");
   await Choose("SafetyGearType","Other");Click("Calculate P5–P7");Check(Result().P5.Status=="UNSUPPORTED_CONFIGURATION"&&Result().P5.PerComponentLoadN==null&&Result().P7.PerComponentLoadN.HasValue,"Unsupported safety type specifically unavailable, buffers independent");await Choose("SafetyGearType","Progressive");
   await Choose("CarAdditionalMassAllocation","FractionParticipates");Editors()["Calculations.SafetyPit.CarEventAdditionalMassPercent"].Text="50";Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN==13300,"Percentage allocates existing mass without re-entry");Editors()["Calculations.SafetyPit.CarEventAdditionalMassPercent"].Text="invalid";Click("Calculate P5–P7");Check(Result().P5.Status=="INVALID_INPUT"&&Result().P6.PerComponentLoadN==null&&Result().P7.PerComponentLoadN==29600&&Text().Contains("finite percentage"),"Malformed allocation unavailable for car only; CW buffer stays available");Click("Calculate load distribution");Check(Space().Result.Reactions!=null,"Malformed event percentage does not block Basic workflow");await Choose("CarAdditionalMassAllocation","AllParticipates");Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN==16300,"Unused invalid percentage draft does not block all-mass choice");
   Session().FilePath=Path.Combine(output,"SYNTHETIC-UI-saved.elevator.json");Click("Save");var opened=new ProjectSession(new ElevatorProject());opened.Open(Session().FilePath);opened.Save(Path.Combine(output,"SYNTHETIC-UI-save-as.elevator.json"));Check(opened.Project.Calculations.Mode=="Basic"&&opened.Project.Calculations.SafetyPit.CarBufferCount==2&&opened.Project.Calculations.SafetyPit.CarBufferSharing=="EqualSharing"&&opened.Project.Calculations.CarSideAdditionalSuspendedMassKg==600,"Save/open/save-as preserve shared masses, mode and additional inputs");Set("session",opened);Call("ResetCalculations");Call("ShowPage","CALCULATIONS");await Pit();Click("Calculate P5–P7");Check(Result().P5.PerComponentLoadN==16300&&Choices()["CarBufferCount"].SelectedValue.ToString()=="2","Reopened UI restores choices and recalculates correctly");
   w.Width=760;w.Height=640;await Ready();((ScrollViewer)Get("pageScroll")).ScrollToBottom();await Shot("05-narrow-scroll");Check(((ScrollViewer)Get("pageScroll")).ScrollableHeight>0,"Resized page remains scrollable with preview and all controls");w.Width=1220;w.Height=820;
   // Separate live 1:1 drawing project; the note fixture is not installed as a default.
   var live=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(bin,"reviewed-example.elevator.json")));live.Info.Name="SYNTHETIC LIVE DRAWING — INCOMPLETE EVENT INPUTS";Set("session",new ProjectSession(live));Call("ResetCalculations");Call("ShowPage","CALCULATIONS");Check(Session().Project.Calculations.Mode=="Basic"&&Choices()["CarGuideCount"].SelectedValue==null&&Session().Project.Calculations.CarMassKg==null,"Older empty project stays Basic with missing event quantities and masses");Set("outputFolder",output);Set("outputName","MissingSafetyInputs-AllFour.dwg");Call("ShowPage","DRAWINGS");await (Task)Call("Generate");var native=(GenerationResponse)Get("last");Check(native.Success&&native.ViewsGenerated.Length==4,"Missing safety/pit data does not block native four-view generation");Wire.Write(Path.Combine(output,"native-missing-event-inputs.json"),native);
   live.Calculations.SafetyPit=opened.Project.Calculations.SafetyPit;live.Calculations.CarMassKg=550;live.Calculations.CounterweightMassKg=740;live.Calculations.MachineMassKg=300;live.Calculations.CarSideAdditionalSuspendedMassKg=600;Set("session",new ProjectSession(live));Call("ResetCalculations");Set("outputName","StoredSafetyInputs-AllFour.dwg");Call("ShowPage","DRAWINGS");await (Task)Call("Generate");native=(GenerationResponse)Get("last");Check(native.Success&&native.ViewsGenerated.Length==4,"Populated event inputs survive actual native save/reopen roundtrip");Wire.Write(Path.Combine(output,"native-populated-event-inputs.json"),native);
   exit=0;
  }catch(Exception ex){Wire.Write(Path.Combine(output,"ui-error.json"),new{Error=ex.ToString()});}finally{Wire.Write(Path.Combine(output,"safety-pit-ui-tests.json"),new{Status=exit==0?"PASS":"FAIL",Assertions=checks,Checks=names,Method="Real WPF controls driven by programmatic events and rendered screenshots; native AutoCAD Core Console generation/reopen. Not interactive mouse/keyboard testing."});w.Close();}};app.Run(w);return exit;
 }
 static FrameworkElement AsFramework(this DependencyObject item){return (FrameworkElement)item;}
}
